import {writeFileSync,readFileSync} from 'node:fs';
import {runInNewContext} from 'node:vm';
import ts from 'typescript';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {sourceHash} from '../scripts/quality-inventory';
const cases=[
 {name:'default-export-call',source:'export default record("executed");'},
 {name:'named-binding-control',source:'const value = record("executed"); export default value;'},
 {name:'optional-access',source:'export function read(value: { field?: string } | null) { return value?.field; }\nrecord(read(null)); record(read({field:"present"}));'},
 {name:'explicit-null-control',source:'export function read(value: { field?: string } | null) { return value === null ? undefined : value.field; }\nrecord(read(null)); record(read({field:"present"}));'},
];
const results=[];
for(const fixture of cases){
 const file='synthetic/'+fixture.name+'.ts';
 const built=instrumentTypeScriptWithCoverage(fixture.source,file);
 const calls:unknown[]=[];
 const sandbox:any={exports:{},record:(value:unknown)=>{calls.push(value===undefined?'undefined':value);return value;}};
 const output=ts.transpileModule(built.code,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS}}).outputText;
 runInNewContext(output,sandbox,{timeout:1000});
 const summary=createCoverageMap(sandbox.__coverage__).getCoverageSummary().data;
 results.push({name:fixture.name,source:fixture.source,calls,metrics:Object.fromEntries(['statements','branches','functions','lines'].map(m=>[m,summary[m]]))});
}
if(results[0].calls[0]!=='executed'||results[0].metrics.statements.total!==0||results[1].metrics.statements.covered<1)throw Error('Export boundary not reproduced');
if(JSON.stringify(results[2].calls)!==JSON.stringify(results[3].calls))throw Error('Optional/control behavior differs');
const result={command:'bun .git/b04-counter-boundary-probe.ts',runtime:Bun.version,scope:'Synthetic in-memory VM only; no production module executed. Probe assertions describe existing gaps, not passing release behavior.',instrumenterSourceHash:sourceHash(readFileSync('scripts/run-istanbul-bun-coverage.ts','utf8')),probeSource:readFileSync('.git/b04-counter-boundary-probe.ts','utf8'),results};
writeFileSync('.git/b04-counter-boundary-probe.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(results));
